// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

contract Vault {
    IERC20 public immutable asset;

    // Shares are scaled up 1e6x relative to assets. The first depositor mints
    // assets * SHARE_SCALE shares, so a share is always "small" relative to a
    // wei of assets. This makes donation-based share-price inflation require
    // ~1,000,000x the victim's deposit in attacker capital, while keeping
    // redemption fully proportional: the sole (or last) holder redeems the
    // entire balance, so plain-transfer yield accrues pro-rata with no
    // virtual-share leakage.
    uint256 private constant SHARE_SCALE = 1e6;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;

    uint256 private _locked = 1;

    modifier nonReentrant() {
        require(_locked == 1, "REENTRANCY");
        _locked = 2;
        _;
        _locked = 1;
    }

    constructor(address _asset) {
        require(_asset != address(0), "ZERO_ASSET");
        asset = IERC20(_asset);
    }

    function totalAssets() public view returns (uint256) {
        return asset.balanceOf(address(this));
    }

    function deposit(uint256 assets) external nonReentrant returns (uint256 shares) {
        uint256 supply = totalSupply;
        // Price against the balance BEFORE this deposit's assets arrive, so a
        // pre-existing donation is treated as yield owned by current holders
        // (or captured by the first depositor if there are none).
        uint256 total = totalAssets();

        if (supply == 0) {
            shares = assets * SHARE_SCALE;
        } else {
            shares = _mulDiv(assets, supply, total);
        }
        require(shares != 0, "ZERO_SHARES");

        _safeTransferFrom(msg.sender, assets);

        totalSupply = supply + shares;
        balanceOf[msg.sender] += shares;
    }

    function redeem(uint256 shares) external nonReentrant returns (uint256 assets) {
        if (shares == 0) {
            return 0;
        }
        uint256 supply = totalSupply;
        // Rounds down, so a round trip can never extract more than was put in,
        // and the sum of all redemptions can never exceed the balance held.
        assets = _mulDiv(shares, totalAssets(), supply);

        balanceOf[msg.sender] -= shares;
        totalSupply = supply - shares;

        if (assets != 0) {
            _safeTransfer(msg.sender, assets);
        }
    }

    function _safeTransfer(address to, uint256 amount) private {
        (bool ok, bytes memory data) =
            address(asset).call(abi.encodeWithSelector(IERC20.transfer.selector, to, amount));
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FAILED");
    }

    function _safeTransferFrom(address from, uint256 amount) private {
        (bool ok, bytes memory data) = address(asset).call(
            abi.encodeWithSelector(IERC20.transferFrom.selector, from, address(this), amount)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FROM_FAILED");
    }

    // Full-precision floor(x * y / denominator); the 512-bit intermediate
    // keeps large deposits from overflowing the share math.
    function _mulDiv(uint256 x, uint256 y, uint256 denominator) private pure returns (uint256 result) {
        unchecked {
            uint256 prod0;
            uint256 prod1;
            assembly {
                let mm := mulmod(x, y, not(0))
                prod0 := mul(x, y)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }

            if (prod1 == 0) {
                return prod0 / denominator;
            }

            require(denominator > prod1, "MULDIV_OVERFLOW");

            uint256 remainder;
            assembly {
                remainder := mulmod(x, y, denominator)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }

            uint256 twos = denominator & (0 - denominator);
            assembly {
                denominator := div(denominator, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }

            prod0 |= prod1 * twos;

            uint256 inverse = (3 * denominator) ^ 2;

            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;

            result = prod0 * inverse;
        }
    }
}
